(function(){var st=document.getElementById('pyt-css');if(!st){st=document.createElement('style');st.id='pyt-css';st.textContent="/* Тренажёр КР по Python, встроен в конспект Учёбы: цвета берутся из переменных темы Учёбы */\n.pyt{--a1:var(--accent);--a2:var(--accent);margin:18px 0 8px;font-family:var(--sans)}\n.prose .pyt h2,.prose .pyt h3,.prose .pyt h4,.prose .pyt h5{font-family:var(--sans);font-style:normal;text-transform:none;letter-spacing:0;text-align:left;color:var(--fg);padding:0;border:0;background:none;display:block;line-height:1.25}\n.prose .pyt h2:before,.prose .pyt h2:after,.prose .pyt h3:before,.prose .pyt h3:after,.prose .pyt h4:before,.prose .pyt h4:after{content:none!important;display:none}\n.prose .pyt h2{font-size:1.3em;font-weight:700;margin:0 0 8px}\n.prose .pyt h3{font-size:1.1em;font-weight:700;margin:2px 0 6px}\n.prose .pyt h4{font-size:.78em;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin:14px 0 4px}\n.prose .pyt h5{font-size:1em;font-weight:700;margin:0 0 6px}\n.prose .pyt p{text-indent:0}.prose .pyt p:first-child:first-letter{all:unset}\n.prose .pyt pre{margin:6px 0;white-space:pre-wrap}\n.prose .pyt table{width:100%}\n.pm{font:13px/1.35 ui-monospace,'SF Mono','JetBrains Mono',Menlo,Consolas,monospace}\n.pyt code,.pyt pre,.pyt textarea{font-family:ui-monospace,'SF Mono','JetBrains Mono',Menlo,Consolas,monospace}\n.pbtn{height:42px;padding:0 18px;border:1px solid var(--line);border-radius:999px;background:var(--surface);color:var(--fg);font:500 14px/1 'IBM Plex Sans',system-ui,sans-serif;cursor:pointer;white-space:nowrap}\n.pbtn:hover:not(:disabled){border-color:var(--faint)}\n.pbtn:disabled{opacity:.45;cursor:not-allowed}\n.pbtn.pri{background:var(--a2);border-color:var(--a2);color:var(--surface);font-weight:600}\n.pbtn.pri:hover:not(:disabled){filter:brightness(1.07)}\n.pbtn.sm{height:34px;padding:0 13px;font-size:13px}\n.pbtn.big{height:50px;padding:0 30px;font-size:16px}\n/* меню */\n.pmodes{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:12px;margin:18px 0 6px}\n.pmode{text-align:left;padding:15px 17px;border:1px solid var(--line);border-radius:16px;background:var(--surface);color:var(--fg);cursor:pointer;display:flex;flex-direction:column;gap:5px;transition:border-color .15s}\n.pmode b{font:600 16px/1.2 'IBM Plex Sans',system-ui,sans-serif}.pmode small{color:var(--muted);font:400 13.5px/1.4 'IBM Plex Sans',system-ui,sans-serif}\n.pmode:hover{border-color:var(--faint)}.pmode.on{border-color:var(--a2);box-shadow:inset 0 -3px 0 var(--a2)}\n.ph3{margin:26px 0 10px;font:600 12px/1.2 'IBM Plex Sans',sans-serif;letter-spacing:.09em;text-transform:uppercase;color:var(--faint)}\n.pvars{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:12px}\n.pvar{display:flex;flex-direction:column;gap:6px;padding:16px 17px;border:1px solid var(--line);border-radius:16px;background:var(--surface)}\n.pvar h3{margin:0;font:600 18px/1.2 'IBM Plex Sans',system-ui,sans-serif;display:flex;align-items:center;gap:10px}\n.pvar h3 i{display:inline-grid;place-items:center;width:34px;height:34px;border-radius:50%;background:color-mix(in srgb,var(--a2) 14%,var(--surface));color:var(--a2);font:700 16px 'IBM Plex Sans',sans-serif;font-style:normal}\n.pvar p{margin:0;color:var(--muted);font:400 14px/1.4 'IBM Plex Sans',system-ui,sans-serif}\n.pvar .pp{display:flex;gap:4px;flex-wrap:wrap;margin:4px 0 8px}\n.pdot{width:22px;height:8px;border-radius:4px;background:var(--line)}.pdot.ok{background:#2a9d5c}.pdot.bad{background:#d9534f}\n.pvar .prow{display:flex;gap:8px;flex-wrap:wrap;margin-top:auto}\n.pnote{margin:18px 0 0;padding:12px 15px;border:1px dashed var(--line);border-radius:12px;color:var(--muted);font:400 13.5px/1.5 'IBM Plex Sans',system-ui,sans-serif}\n/* верхняя панель */\n.pbar{display:flex;align-items:center;gap:10px 14px;flex-wrap:wrap;margin:16px 0 10px}\n.pbar .ptt{font:600 16px 'IBM Plex Sans',sans-serif}\n.pbar .pspc{flex:1}\n.pbadge{padding:5px 11px;border-radius:999px;border:1px solid var(--line);font:500 12.5px 'IBM Plex Sans',sans-serif;color:var(--muted)}\n.pbadge.ex{border-color:var(--a1);color:var(--a1)}\n.ptimer{font:600 18px ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums}\n.ptimer.low{color:#d9534f}\n.pscore{font:500 13.5px 'IBM Plex Sans',sans-serif;color:var(--muted)}.pscore b{color:var(--fg)}\n.ptabs{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 14px}\n.ptab{min-width:46px;height:44px;padding:0 10px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--fg);cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;font:600 15px/1 'IBM Plex Sans',sans-serif;position:relative}\n.ptab small{font:400 10.5px/1 'IBM Plex Sans',sans-serif;color:var(--faint)}\n.ptab.cur{border-color:var(--a2);box-shadow:inset 0 -3px 0 var(--a2)}\n.ptab.ok{background:color-mix(in srgb,#2a9d5c 16%,var(--surface))}\n.ptab.ok::after{content:\"✓\";position:absolute;top:2px;right:5px;font-size:11px;color:#2a9d5c}\n.ptab.bad::after{content:\"✗\";position:absolute;top:2px;right:5px;font-size:11px;color:#d9534f}\n/* сетка задачи */\n.pgrid{display:grid;grid-template-columns:minmax(0,1fr);gap:18px;align-items:start}\n@media(min-width:1000px){.pgrid{grid-template-columns:minmax(0,5fr) minmax(0,6fr)}.ptask{position:sticky;top:calc(var(--hdr,0px) + 14px);max-height:calc(100vh - var(--hdr,0px) - 30px);overflow:auto}main:has(.pyt.inwork){max-width:min(1240px,100%)!important}.note-wrap:has(.pyt.inwork){grid-template-columns:minmax(0,1fr)!important}.note:has(.pyt.inwork){max-width:100%!important}.pqb,.pqc{display:none!important}}\n.pqc{display:none;margin:0 0 10px}\n.pqb{position:sticky;top:54px;z-index:6;align-self:flex-end;background:var(--surface)}\n#pqs{position:fixed;inset:0;z-index:98;background:rgba(0,0,0,.42);display:flex;align-items:flex-start;justify-content:center;padding:54px 8px 8px;box-sizing:border-box}\n#pqs .ptask{width:100%;max-width:680px;max-height:100%;overflow:auto;box-sizing:border-box;box-shadow:0 14px 44px rgba(0,0,0,.4);position:static}\n#pqs .pqc{display:inline-block!important}\n.ptask{padding:18px 20px;border:1px solid var(--line);border-radius:16px;background:var(--surface)}\n.ptask h2{margin:0 0 6px;font:600 21px/1.25 'IBM Plex Sans',system-ui,sans-serif}\n.ptask .pmeta{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 12px}\n.ptask .pmeta span{padding:3px 10px;border-radius:999px;border:1px solid var(--line);font:500 12px 'IBM Plex Sans',sans-serif;color:var(--muted)}\n.ptask .pmeta span.pts{border-color:var(--a2);color:var(--a2)}\n.ptask p{margin:0 0 10px;font:400 15.5px/1.6 'Literata',Georgia,serif}\n.ptask p code,.psol li code,.psol p code,.pout-tip code{padding:1px 6px;border-radius:6px;background:color-mix(in srgb,var(--fg) 7%,var(--surface));font-size:.9em}\n.ptask h4{margin:14px 0 4px;font:600 11.5px/1.2 'IBM Plex Sans',sans-serif;letter-spacing:.08em;text-transform:uppercase;color:var(--faint)}\n.pex{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:0 0 8px}\n.pex>div{min-width:0}\n.pex small{display:block;margin:0 0 3px;font:500 11.5px 'IBM Plex Sans',sans-serif;color:var(--faint)}\n.pbk{margin:0;padding:9px 11px;border:1px solid var(--line);border-radius:10px;background:color-mix(in srgb,var(--fg) 4%,var(--surface));font:13px/1.45 ui-monospace,'SF Mono',Menlo,Consolas,monospace;white-space:pre;overflow:auto;color:var(--fg);min-height:2.2em}\n/* редактор */\n.pcode{min-width:0;display:flex;flex-direction:column;gap:10px}\n.ppre{margin:0;border-radius:12px 12px 0 0}\n.ppre-l{font:500 11.5px 'IBM Plex Sans',sans-serif;color:var(--faint);margin:0 0 -4px}\n#pcode{width:100%;min-height:290px;resize:vertical;padding:12px 14px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--fg);font:14px/1.5 ui-monospace,'SF Mono',Menlo,Consolas,monospace;tab-size:4;white-space:pre;overflow:auto;box-sizing:border-box}\n#pcode:focus{outline:2px solid color-mix(in srgb,var(--a2) 45%,transparent);outline-offset:0;border-color:var(--a2)}\n.pkeys{display:flex;gap:6px;flex-wrap:wrap}\n.pact{display:flex;gap:8px;flex-wrap:wrap}\n.pin{border:1px solid var(--line);border-radius:12px;padding:0 12px;background:var(--surface)}\n.pin summary{padding:10px 0;cursor:pointer;font:500 13.5px 'IBM Plex Sans',sans-serif;color:var(--muted)}\n.pin textarea{width:100%;min-height:90px;margin:0 0 12px;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:color-mix(in srgb,var(--fg) 4%,var(--surface));color:var(--fg);font:13px/1.45 ui-monospace,Menlo,Consolas,monospace;box-sizing:border-box}\n.pst{font:500 12.5px 'IBM Plex Sans',sans-serif;color:var(--faint);min-height:1.2em}\n.pst.err{color:#d9534f}\n/* результаты */\n.pout{display:flex;flex-direction:column;gap:10px}\n.pbox{border:1px solid var(--line);border-radius:12px;padding:12px 14px;background:var(--surface)}\n.pbox h5{margin:0 0 6px;font:600 13px 'IBM Plex Sans',sans-serif}\n.pbox.ok{border-color:#2a9d5c;background:color-mix(in srgb,#2a9d5c 9%,var(--surface))}\n.pbox.bad{border-color:#d9534f;background:color-mix(in srgb,#d9534f 7%,var(--surface))}\n.pbox.err{border-color:#d9534f}\n.pbox .pbk{background:var(--bg)}\n.ptests{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 8px}\n.pt{padding:4px 10px;border-radius:999px;font:600 12px 'IBM Plex Sans',sans-serif;border:1px solid var(--line);color:var(--muted)}\n.pt.ok{border-color:#2a9d5c;color:#2a9d5c}.pt.bad{border-color:#d9534f;color:#d9534f}\n.pdiff{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:8px 0}\n.pdiff small{display:block;margin:0 0 3px;font:500 11.5px 'IBM Plex Sans',sans-serif;color:var(--faint)}\n.pdiff .pbk .bad{background:color-mix(in srgb,#d9534f 22%,transparent);display:inline-block;min-width:100%}\n.pout-tip{margin:8px 0 0;font:400 14px/1.5 'IBM Plex Sans',system-ui,sans-serif}\n.pout-tip ul{margin:4px 0 0;padding-left:20px}\n/* разбор */\n.psol{margin-top:18px;padding:18px 20px;border:1px solid var(--a2);border-radius:16px;background:var(--surface)}\n.psol h3{margin:0 0 10px;font:600 19px 'IBM Plex Sans',sans-serif}\n.psol h4{margin:16px 0 6px;font:600 11.5px 'IBM Plex Sans',sans-serif;letter-spacing:.08em;text-transform:uppercase;color:var(--faint)}\n.psol p,.psol li{font:400 15.5px/1.6 'Literata',Georgia,serif}\n.psol ol,.psol ul{margin:0;padding-left:22px}.psol li{margin:0 0 5px}\n.psol .ptrace{padding:10px 13px;border-radius:10px;background:color-mix(in srgb,var(--fg) 5%,var(--surface));margin:0}\n.psol .prow{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}\n.hk{color:var(--a1);font-weight:600}.hs{color:#2a9d5c}.hn{color:#c77d1a}.hc{color:var(--faint);font-style:italic}.hb{color:#6a5acd}\n/* итог */\n.ptbl{width:100%;border-collapse:collapse;margin:8px 0 16px;font:400 14.5px 'IBM Plex Sans',sans-serif}\n.ptbl th,.ptbl td{padding:9px 10px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}\n.ptbl th{font-weight:600;color:var(--faint);font-size:12px;letter-spacing:.05em;text-transform:uppercase}\n.ptblw{overflow-x:auto}\n.pbig{font:700 44px/1 'IBM Plex Sans',sans-serif;margin:6px 0}\n.pbig small{font:500 16px 'IBM Plex Sans',sans-serif;color:var(--muted)}\n@media(max-width:560px){.pex,.pdiff{grid-template-columns:1fr}.ptask{padding:15px 15px}.psol{padding:15px}.pbtn{height:44px}.pbtn.sm{height:36px}#pcode{font-size:16px;min-height:260px}}\n@media(prefers-reduced-motion:reduce){.pmode,.pbtn{transition:none}}\n\n.ptask h2{text-align:left!important;font:600 20px/1.25 'IBM Plex Sans',system-ui,sans-serif!important;padding:0!important;margin:0 0 6px!important;font-style:normal!important;letter-spacing:0!important;text-transform:none!important}\n.ptask h4{text-align:left!important;font:600 11.5px/1.2 'IBM Plex Sans',system-ui,sans-serif!important;font-style:normal!important;letter-spacing:.08em!important;text-transform:uppercase!important;margin:14px 0 4px!important;padding:0!important;color:var(--faint)!important}\n";document.head.appendChild(st)}})();
var PYD=[{"id":"A","name":"Вариант А","sub":"Библиотека и банк","tasks":[{"id":"A1","n":1,"pts":0.5,"title":"Выдача книги","topics":"if / elif / else, not in","text":"В окне уже заданы список `readers` и три фразы: `ok_msg`, `late_msg`, `other_msg`. Вводятся имя читателя и число дней просрочки прошлой книги.\n\nЕсли имени нет в списке читателей, напечатайте `other_msg`. Если читатель есть и просрочки нет (0 дней), напечатайте `ok_msg`. Если читатель есть и просрочка есть, напечатайте `late_msg`.","fin":"Первая строка — имя, вторая — число дней (целое).","fout":"Одна из трёх фраз.","pre":"readers = ['Ольга', 'Павел', 'Иван']\nok_msg = 'Книга выдана'\nlate_msg = 'Сначала верните прошлую книгу'\nother_msg = 'Сначала запишитесь в библиотеку'","tests":[{"i":"Ольга\n0","o":"Книга выдана"},{"i":"Павел\n5","o":"Сначала верните прошлую книгу"},{"i":"Анна\n0","o":"Сначала запишитесь в библиотеку"},{"i":"Иван\n1","o":"Сначала верните прошлую книгу"},{"i":"Ольга\n30","o":"Сначала верните прошлую книгу"},{"i":"ольга\n0","o":"Сначала запишитесь в библиотеку"}],"sol":"name = input()\ndays = int(input())\n\nif name not in readers:\n    print(other_msg)\nelif days == 0:\n    print(ok_msg)\nelse:\n    print(late_msg)","hint":"Сначала отсеките тех, кого нет в списке (`not in`), потом разберите просрочку через `elif` и `else`. Не забудьте `int` для дней.","idea":"Три исхода — цепочка `if / elif / else`: нет в списке; в списке без просрочки; в списке с просрочкой.","steps":["`name = input()` читает имя, `days = int(input())` читает дни и сразу делает их числом.","`name not in readers` — первая проверка: если читателя нет, остальное не важно.","`elif days == 0` выполняется только когда читатель есть; сравнение на равенство — два знака `==`.","`else` — читатель есть и просрочка больше нуля."],"mist":["Забыли `int(...)`: сравнение `\"0\" == 0` даёт `False`, и все получат `late_msg`.","Поставили `=` вместо `==` в условии: будет `SyntaxError`.","Регистр важен: `ольга` не равно `Ольга`, такого читателя в списке нет."],"trace":""},{"id":"A2","n":2,"pts":1,"title":"Новые книги","topics":"while True, break, split, список","text":"Вводятся строки вида `название:год` (год — целое число), пока не будет введено слово `END`.\n\nНапечатайте список названий книг, изданных **после 2000 года** (строго), в порядке ввода. Если таких нет, напечатайте пустой список.","fin":"Строки `название:год`, последняя строка — `END`.","fout":"Список названий в квадратных скобках, как печатает `print(список)`.","pre":"","tests":[{"i":"Мастер и Маргарита:1967\nДюна:1965\nГарри Поттер:2001\nEND","o":"['Гарри Поттер']"},{"i":"END","o":"[]"},{"i":"Книга:2000\nДругая:2024\nТретья:1999\nЧетвёртая:2010\nEND","o":"['Другая', 'Четвёртая']"},{"i":"Война и мир:1869\nEND","o":"[]"},{"i":"А:2001\nEND","o":"['А']"}],"sol":"new = []\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    title, year = line.split(':')\n    if int(year) > 2000:\n        new.append(title)\n\nprint(new)","hint":"Список создайте до цикла. Строку режьте по двоеточию: `title, year = line.split(\":\")`. Год — строка, нужен `int`.","idea":"Читаем строки в бесконечном цикле, на слове `END` выходим через `break`, остальное разбираем и фильтруем.","steps":["`new = []` создаём **до** цикла, иначе список обнулялся бы на каждой строке.","`while True:` — читаем, пока сами не прервём цикл.","`line == \"END\"` → `break`: выходим, не обрабатывая слово `END`.","`title, year = line.split(\":\")` — две части строки в две переменные.","`int(year) > 2000` — строго «после 2000», значит 2000 не подходит."],"mist":["Список создан внутри цикла — в конце останется только последняя книга.","Не сделали `int(year)`: сравнение строки `\"2001\"` с числом 2000 — ошибка `TypeError`.","Поставили `>=`: книга 2000 года попадёт в список зря."],"trace":"Ввод `Мастер и Маргарита:1967`: 1967 не больше 2000, пропускаем. `Дюна:1965` — пропускаем. `Гарри Поттер:2001` — 2001 больше 2000, добавляем. `END` — выходим. Печатаем `['Гарри Поттер']`."},{"id":"A3","n":3,"pts":0.5,"title":"Новая книга в каталоге","topics":"split(\", \"), not in, append","text":"В первой строке названия книг каталога через «запятая + пробел». Во второй — название новой книги.\n\nЕсли такой книги в каталоге ещё нет, добавьте её в конец списка. Напечатайте список.","fin":"Первая строка — названия через `, `. Вторая — одно название.","fout":"Список названий в квадратных скобках.","pre":"","tests":[{"i":"Дюна, Эмма, Идиот\nБелая гвардия","o":"['Дюна', 'Эмма', 'Идиот', 'Белая гвардия']"},{"i":"Дюна, Эмма\nЭмма","o":"['Дюна', 'Эмма']"},{"i":"Ревизор\nРевизор","o":"['Ревизор']"},{"i":"Мцыри, Дубровский\nАнна Каренина","o":"['Мцыри', 'Дубровский', 'Анна Каренина']"},{"i":"Дюна\nдюна","o":"['Дюна', 'дюна']"}],"sol":"books = input().split(', ')\nnew_book = input()\n\nif new_book not in books:\n    books.append(new_book)\n\nprint(books)","hint":"Строку с названиями разбейте `split(\", \")` (запятая и пробел). Проверка — `not in`, добавление — `append`.","idea":"Превращаем строку в список, проверяем, нет ли там новой книги, и добавляем при необходимости.","steps":["`input().split(\", \")` — строка превращается в список названий; названия с пробелом внутри остаются целыми.","`new_book not in books` — истина, если такой книги в списке нет.","`books.append(new_book)` добавляет в конец и меняет сам список.","Печатаем в конце, чтобы вывод был и когда книга уже была."],"mist":["`split()` без аргумента режет и по пробелам внутри названий, и запятые остаются в кусках.","`print` внутри `if`: если книга уже есть, ничего не напечатается.","Результат `append` присвоили переменной: `books = books.append(...)` даёт `None`."],"trace":""},{"id":"A4","n":4,"pts":1,"title":"Выгодные вклады","topics":"два списка, range(len())","text":"В первой строке названия вкладов через пробел, во второй — их годовые ставки (целые числа процентов) в том же порядке. В третьей — минимальная ставка, которая вас устраивает.\n\nНапечатайте названия вкладов, у которых ставка **не меньше** минимальной, каждое с новой строки.","fin":"Три строки: названия, ставки, минимальная ставка.","fout":"Названия по одному на строке или пустой вывод.","pre":"","tests":[{"i":"Старт Лето Мир Плюс\n8 12 10 15\n10","o":"Лето\nМир\nПлюс"},{"i":"А Б\n5 6\n7","o":""},{"i":"Один\n9\n9","o":"Один"},{"i":"Весна Осень Зима\n11 7 11\n11","o":"Весна\nЗима"},{"i":"Х У\n20 1\n1","o":"Х\nУ"}],"sol":"deposits = input().split()\nrates = input().split()\nneed = int(input())\n\nfor i in range(len(deposits)):\n    if int(rates[i]) >= need:\n        print(deposits[i])","hint":"Названия и ставки лежат в двух списках, связь между ними — одинаковый номер. Переберите номера через `range(len(...))`. Ставки — строки, нужен `int`.","idea":"Идём по номерам: по номеру берём и название, и ставку, сравниваем ставку с минимальной.","steps":["`deposits` и `rates` — списки **строк**; число из `rates` нужно через `int(rates[i])`.","`range(len(deposits))` — номера 0, 1, 2, …","`int(rates[i]) >= need` — «не меньше», то есть `>=`.","Печатаем `deposits[i]` — название с тем же номером."],"mist":["`>` вместо `>=`: вклад со ставкой ровно как минимальная пропадёт.","Сравнили `rates[i] >= need` без `int`: строка с числом — ошибка `TypeError`.","Напечатали `rates[i]` вместо `deposits[i]`."],"trace":""},{"id":"A5","n":5,"pts":0.75,"title":"Общие читатели","topics":"множества, пересечение","text":"Две строки: имена читателей первого филиала и второго (через пробел).\n\nНапечатайте через пробел имена, которые есть **в обоих** филиалах, в алфавитном порядке. Если общих нет, напечатайте пустую строку.","fin":"Две строки, имена через пробел.","fout":"Имена через пробел в алфавитном порядке или пустая строка.","pre":"","tests":[{"i":"Аня Борис Вера\nВера Глеб Аня","o":"Аня Вера"},{"i":"Аня\nБорис","o":""},{"i":"Дима Егор Жанна\nЖанна Дима Егор","o":"Дима Егор Жанна"},{"i":"Зоя\nЗоя Ира","o":"Зоя"},{"i":"Паша Рита\nСергей Тоня","o":""}],"sol":"first = set(input().split())\nsecond = set(input().split())\n\nprint(*sorted(first & second))","hint":"Превратите обе строки во множества, найдите пересечение `&`, отсортируйте `sorted` и распечатайте через `print(*...)`.","idea":"Общие элементы двух множеств — их пересечение. Порядок во множестве не определён, поэтому сортируем.","steps":["`set(input().split())` — строка → список → множество.","`first & second` — имена, которые есть в обоих множествах.","`sorted(...)` даёт список по алфавиту.","`print(*список)` печатает элементы через пробел; для пустого списка получится пустая строка."],"mist":["`print(first & second)` печатает фигурные скобки и порядок случайный.","`|` вместо `&`: получатся все читатели, а не общие.","Забыли `sorted`: порядок имён может отличаться от ожидаемого."],"trace":""},{"id":"A6","n":6,"pts":1.25,"title":"Невостребованные жанры","topics":"множества, объединение и разность","text":"Три строки с названиями жанров через запятую **без пробела** (в названиях пробелы бывают): жанры, которые читает Аня; жанры, которые читает Борис; все жанры библиотеки.\n\nНапечатайте, сколько жанров библиотеки **не читает ни Аня, ни Борис**.","fin":"Три строки, жанры через запятую.","fout":"Одно число.","pre":"","tests":[{"i":"Детектив,Фэнтези\nФэнтези,Поэзия\nДетектив,Фэнтези,Поэзия,Научная фантастика,Драма","o":"2"},{"i":"А б,В г\nД е\nЖ з","o":"1"},{"i":"Х\nХ\nХ","o":"0"},{"i":"Роман\nРоман,Эссе\nРоман,Эссе,Комикс","o":"1"},{"i":"Драма,Поэзия\nПоэзия\nДрама,Поэзия,Сказки","o":"1"}],"sol":"anna = set(input().split(','))\nboris = set(input().split(','))\nlibrary = set(input().split(','))\n\nchosen = anna | boris\nprint(len(library - chosen))","hint":"«Ни Аня, ни Борис» — это жанры, которых нет в объединении их множеств. Сначала объедините `|`, потом вычтите `-` из множества библиотеки.","idea":"Собираем всё, что читает хотя бы один (объединение), и вычитаем это из жанров библиотеки.","steps":["Разделитель — запятая без пробела: `.split(\",\")`. Без аргумента названия с пробелами разорвутся.","`anna | boris` — жанры, которые читает хотя бы один из двоих.","`library - chosen` — жанры библиотеки, которых нет среди читаемых.","`len(...)` — сколько их."],"mist":["`split()` вместо `split(\",\")`: «Научная фантастика» разорвётся на два жанра.","Вычли в другую сторону `chosen - library`: получится совсем другое множество.","`&` вместо `|` в первом шаге: получатся жанры «читают оба»."],"trace":""},{"id":"A7","n":7,"pts":0.75,"title":"Клиенты банка","topics":"словарь, перебор ключей","text":"В окне задан словарь `accounts`: клиент → банк, в котором у него счёт. Вводится название банка.\n\nНапечатайте клиентов этого банка, каждого с новой строки, в порядке словаря. Если таких нет, ничего не печатайте.","fin":"Одна строка — название банка.","fout":"Имена по одному на строке или пустой вывод.","pre":"accounts = {'Анна': 'Север', 'Борис': 'Юг', 'Вера': 'Север', 'Глеб': 'Запад', 'Дарья': 'Юг', 'Егор': 'Север'}","tests":[{"i":"Север","o":"Анна\nВера\nЕгор"},{"i":"Юг","o":"Борис\nДарья"},{"i":"Запад","o":"Глеб"},{"i":"Восток","o":""},{"i":"север","o":""}],"sol":"bank = input()\n\nfor name in accounts:\n    if accounts[name] == bank:\n        print(name)","hint":"Цикл `for name in accounts` перебирает **ключи** (клиентов). Значение (банк) берётся как `accounts[name]`.","idea":"Идём по клиентам и печатаем тех, у кого банк совпадает с введённым.","steps":["`for name in accounts:` — переменная `name` по очереди получает каждого клиента.","`accounts[name]` — банк этого клиента.","`== bank` — совпадение с введённым названием.","Печатаем `name`, а не банк."],"mist":["Напечатали `accounts[name]`: получится название банка вместо клиента.","Ждали, что цикл даст значения: он перебирает ключи.","Сравнили без учёта регистра: `север` не равно `Север`."],"trace":""},{"id":"A8","n":8,"pts":1.25,"title":"Филиалы без перегрузки","topics":"словарь списков, max","text":"В окне задан словарь `branches`: филиал → список числа посетителей за четыре дня. Вводится лимит.\n\nНапечатайте филиалы, у которых **в каждый из дней** посетителей **строго меньше** лимита, каждый с новой строки, в порядке словаря.","fin":"Одна строка — лимит (целое число).","fout":"Названия филиалов по одному на строке или пустой вывод.","pre":"branches = {'Центральный': [120, 95, 140, 110], 'Северный': [60, 75, 80, 70], 'Южный': [200, 180, 150, 170], 'Речной': [90, 85, 95, 100]}","tests":[{"i":"150","o":"Центральный\nСеверный\nРечной"},{"i":"100","o":"Северный"},{"i":"50","o":""},{"i":"201","o":"Центральный\nСеверный\nЮжный\nРечной"},{"i":"141","o":"Центральный\nСеверный\nРечной"}],"sol":"limit = int(input())\n\nfor branch in branches:\n    if max(branches[branch]) < limit:\n        print(branch)","hint":"«В каждый день меньше лимита» — это то же, что «самый загруженный день меньше лимита». Используйте `max`.","idea":"Вместо проверки каждого дня сравниваем с лимитом максимум в списке.","steps":["`branches[branch]` — список посетителей филиала.","`max(...)` — самый большой день.","Если самый большой день меньше лимита, то и все остальные меньше. Строго «меньше» — это `<`.","Печатаем **ключ** `branch`, а не список."],"mist":["`min` вместо `max`: условие станет «хотя бы в один день меньше лимита».","`<=` вместо `<`: филиал с пиком ровно в лимит попадёт зря.","Напечатали `branches[branch]` — список посетителей вместо названия."],"trace":""},{"id":"A9","n":9,"pts":1.5,"title":"Книги в коробках","topics":"цикл, // и %","text":"Первая строка — количество книг в каждом заказе, через пробел. Вторая — вместимость одной коробки (целое число). Каждую коробку заполняют только полностью, остаток книг каждого заказа остаётся на полке.\n\nНапечатайте через пробел два числа: сколько **всего полных коробок** получится и сколько **всего книг останется** на полке.","fin":"Две строки: заказы, вместимость коробки.","fout":"Два числа через пробел.","pre":"","tests":[{"i":"25 40 10\n10","o":"7 5"},{"i":"7\n10","o":"0 7"},{"i":"100 100\n25","o":"8 0"},{"i":"1 2 3\n2","o":"2 2"},{"i":"50\n7","o":"7 1"}],"sol":"orders = input().split()\nbox = int(input())\n\nfull = 0\nrest = 0\nfor order in orders:\n    full += int(order) // box\n    rest += int(order) % box\n\nprint(full, rest)","hint":"Для одного заказа число полных коробок — `//` (целочисленное деление), остаток — `%`. Заведите два счётчика до цикла.","idea":"Для каждого заказа делим нацело на вместимость и берём остаток, итоги копим в двух счётчиках.","steps":["`orders` — список **строк**, каждую берём как `int(order)`.","`int(order) // box` — сколько полных коробок в заказе.","`int(order) % box` — сколько книг осталось.","`full` и `rest` создаём **до** цикла, печатаем после."],"mist":["Обнулили счётчики внутри цикла: останутся данные последнего заказа.","Забыли `int(order)`: деление `//` со строкой — ошибка.","Посчитали по общей сумме книг: остаток на заказ даёт другое число."],"trace":"Заказы `25 40 10`, коробка 10: 25 → 2 коробки, остаток 5; 40 → 4, остаток 0; 10 → 1, остаток 0. Итого 7 полных коробок и 5 книг. Печатаем `7 5`."},{"id":"A10","n":10,"pts":1.5,"title":"Самый популярный жанр","topics":"while True, словарь-накопитель, максимум","text":"Вводятся строки вида `жанр,выдач` (число выдач — целое **положительное**), пока не будет введено слово `END`. Один жанр может встретиться несколько раз.\n\nНайдите жанр с **наибольшим суммарным** числом выдач. Напечатайте его название и число через пробел. Гарантируется, что есть хотя бы одна строка. Если у нескольких жанров одинаковый максимум — выведите того, кто встретился раньше.","fin":"Строки `жанр,выдач`, последняя строка — `END`.","fout":"Название и число через пробел.","pre":"","tests":[{"i":"Детектив,10\nПоэзия,4\nДетектив,15\nПоэзия,6\nРоман,25\nEND","o":"Детектив 25"},{"i":"Роман,5\nEND","o":"Роман 5"},{"i":"А,10\nБ,10\nEND","o":"А 10"},{"i":"Х,100\nУ,50\nУ,60\nEND","o":"У 110"},{"i":"Драма,3\nСказки,2\nДрама,1\nСказки,7\nEND","o":"Сказки 9"}],"sol":"totals = {}\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    genre, count = line.split(',')\n    if genre in totals:\n        totals[genre] += int(count)\n    else:\n        totals[genre] = int(count)\n\nbest = ''\nbest_sum = 0\nfor genre in totals:\n    if totals[genre] > best_sum:\n        best_sum = totals[genre]\n        best = genre\n\nprint(best, best_sum)","hint":"Два шага: (1) в цикле копите суммы в словаре; (2) после цикла найдите максимум. Для строгого сравнения при равных суммах берите `>`, а не `>=`.","idea":"Сначала собираем словарь «жанр → выдач», потом ищем ключ с наибольшим значением.","steps":["`totals = {}` — до цикла.","Если жанр уже есть в словаре, прибавляем: `totals[genre] += int(count)`, иначе создаём запись.","Выдач всегда больше нуля, поэтому стартовый максимум `0` подходит: любое значение его заменит.","`>` (строго) оставляет первого из равных, как требует условие.","`print(best, best_sum)` с запятой печатает через пробел."],"mist":["`max(totals)` без `key` берёт максимум **по алфавиту жанров**, а не по числу выдач.","`>=` вместо `>`: при равных суммах выберется последний, а не первый.","Забыли `int(count)`: строки склеиваются (`\"10\" + \"15\"`)."],"trace":"Детектив: 10, затем 15 → 25. Поэзия: 4, затем 6 → 10. Роман: 25. Максимум 25: Детектив встретился раньше Романа, поэтому ответ `Детектив 25`."}]},{"id":"B","name":"Вариант Б","sub":"Школа и турагентство","tasks":[{"id":"B1","n":1,"pts":0.5,"title":"Допуск к экскурсии","topics":"if / elif / else, in, and","text":"В окне уже заданы список `groups` и три фразы: `go_msg`, `stay_msg`, `other_msg`. Вводятся номер класса и ответ родителей (`да` или `нет`).\n\nЕсли класс в списке и ответ `да`, напечатайте `go_msg`. Если класс в списке, но ответ другой, напечатайте `stay_msg`. Если класса нет в списке, напечатайте `other_msg`.","fin":"Первая строка — класс, вторая — ответ.","fout":"Одна из трёх фраз.","pre":"groups = ['5А', '6Б', '7В']\ngo_msg = 'Едете на экскурсию'\nstay_msg = 'Остаётесь в школе'\nother_msg = 'Для вашего класса экскурсии нет'","tests":[{"i":"5А\nда","o":"Едете на экскурсию"},{"i":"6Б\nнет","o":"Остаётесь в школе"},{"i":"8Г\nда","o":"Для вашего класса экскурсии нет"},{"i":"7В\nда","o":"Едете на экскурсию"},{"i":"5А\nнет","o":"Остаётесь в школе"},{"i":"9Д\nнет","o":"Для вашего класса экскурсии нет"}],"sol":"cls = input()\nanswer = input()\n\nif cls in groups and answer == 'да':\n    print(go_msg)\nelif cls in groups:\n    print(stay_msg)\nelse:\n    print(other_msg)","hint":"Сначала проверьте оба условия сразу через `and`, затем вторым шагом только «класс в списке», остальное — `else`.","idea":"Три исхода — цепочка `if / elif / else`: класс в списке и ответ `да`; класс в списке и любой другой ответ; класса нет в списке.","steps":["`cls` и `answer` — две строки ввода. Слово `class` занято в Python, поэтому переменную называют иначе.","`cls in groups and answer == \"да\"` — оба условия верны одновременно.","`elif cls in groups` — сюда попадут только те, у кого ответ не `да`.","`else` — класса нет в списке."],"mist":["Поставили первой проверку `cls in groups`: «да» тогда никогда не дойдёт до своей ветки.","Назвали переменную `class`: это ключевое слово, будет `SyntaxError`.","Забыли кавычки у `да`: Python решит, что это переменная."],"trace":""},{"id":"B2","n":2,"pts":1,"title":"Хорошие оценки","topics":"while True, break, split, список","text":"Вводятся строки вида `ученик:балл` (балл — целое число), пока не будет введено слово `END`.\n\nНапечатайте список учеников, у которых балл **не ниже 8**, в порядке ввода. Если таких нет, напечатайте пустой список.","fin":"Строки `ученик:балл`, последняя строка — `END`.","fout":"Список имён в квадратных скобках, как печатает `print(список)`.","pre":"","tests":[{"i":"Аня:9\nБоря:5\nВера:8\nEND","o":"['Аня', 'Вера']"},{"i":"END","o":"[]"},{"i":"Глеб:7\nДаша:6\nEND","o":"[]"},{"i":"Егор:10\nЖанна:8\nЗоя:3\nИван:9\nEND","o":"['Егор', 'Жанна', 'Иван']"},{"i":"Коля:8\nEND","o":"['Коля']"}],"sol":"good = []\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    name, mark = line.split(':')\n    if int(mark) >= 8:\n        good.append(name)\n\nprint(good)","hint":"Список создайте до цикла. Строку режьте по двоеточию: `name, mark = line.split(\":\")`. Балл — строка, нужен `int`. «Не ниже 8» — это `>=`.","idea":"Читаем строки в бесконечном цикле, на слове `END` выходим через `break`, остальное разбираем и фильтруем.","steps":["`good = []` создаём **до** цикла, иначе список обнулялся бы на каждой строке.","`while True:` — читаем, пока сами не прервём цикл.","`line == \"END\"` → `break`: выходим, не обрабатывая слово `END`.","`name, mark = line.split(\":\")` — две части строки в две переменные.","`int(mark) >= 8` — «не ниже 8» включает сам восьмёрку."],"mist":["Список создан внутри цикла — в конце останется только последний ученик.","Не сделали `int(mark)`: сравнение строки `\"9\"` с числом — ошибка `TypeError`.","Поставили `>`: ученик с баллом ровно 8 пропадёт."],"trace":""},{"id":"B3","n":3,"pts":0.5,"title":"Новый кружок","topics":"split(\", \"), not in, append","text":"В первой строке названия кружков через «запятая + пробел». Во второй — название нового кружка.\n\nЕсли такого кружка ещё нет, добавьте его в конец списка. Напечатайте список.","fin":"Первая строка — названия через `, `. Вторая — одно название.","fout":"Список названий в квадратных скобках.","pre":"","tests":[{"i":"Шахматы, Танцы, Хор\nРобототехника","o":"['Шахматы', 'Танцы', 'Хор', 'Робототехника']"},{"i":"Шахматы, Танцы\nТанцы","o":"['Шахматы', 'Танцы']"},{"i":"Рисование\nРисование","o":"['Рисование']"},{"i":"Футбол, Плавание\nТеннис","o":"['Футбол', 'Плавание', 'Теннис']"},{"i":"Хор\nхор","o":"['Хор', 'хор']"}],"sol":"clubs = input().split(', ')\nnew_club = input()\n\nif new_club not in clubs:\n    clubs.append(new_club)\n\nprint(clubs)","hint":"Строку с названиями разбейте `split(\", \")` (запятая и пробел). Проверка — `not in`, добавление — `append`.","idea":"Превращаем строку в список, проверяем, нет ли там нового кружка, и добавляем при необходимости.","steps":["`input().split(\", \")` — строка превращается в список названий.","`new_club not in clubs` — истина, если такого кружка в списке нет.","`clubs.append(new_club)` добавляет в конец и меняет сам список.","Печатаем в конце, чтобы вывод был и когда кружок уже был."],"mist":["`split()` без аргумента режет по пробелам, а запятые остаются в кусках.","`print` внутри `if`: если кружок уже есть, ничего не напечатается.","`clubs = clubs.append(...)` даёт `None`: `append` ничего не возвращает."],"trace":""},{"id":"B4","n":4,"pts":1,"title":"Недорогие туры","topics":"два списка, range(len())","text":"В первой строке названия туров через пробел, во второй — их цены (целые числа) в том же порядке. В третьей — бюджет.\n\nНапечатайте туры, цена которых **строго меньше** бюджета, каждый с новой строки в виде `тур цена`.","fin":"Три строки: туры, цены, бюджет.","fout":"Строки `тур цена` или пустой вывод.","pre":"","tests":[{"i":"Сочи Казань Алтай Крым\n50000 30000 45000 60000\n46000","o":"Казань 30000\nАлтай 45000"},{"i":"А Б\n100 200\n50","o":""},{"i":"Байкал\n70000\n70001","o":"Байкал 70000"},{"i":"Тур1 Тур2 Тур3\n10 20 30\n30","o":"Тур1 10\nТур2 20"},{"i":"Х У\n5 5\n6","o":"Х 5\nУ 5"}],"sol":"tours = input().split()\nprices = input().split()\nbudget = int(input())\n\nfor i in range(len(tours)):\n    if int(prices[i]) < budget:\n        print(tours[i], prices[i])","hint":"Туры и цены лежат в двух списках, связь между ними — одинаковый номер. Переберите номера через `range(len(...))`. Цены — строки, для сравнения нужен `int`.","idea":"Идём по номерам: по номеру берём и тур, и цену, сравниваем цену с бюджетом и печатаем обе.","steps":["`tours` и `prices` — списки **строк**; цену для сравнения берём как `int(prices[i])`.","`range(len(tours))` — номера 0, 1, 2, …","`int(prices[i]) < budget` — «строго меньше», то есть `<`.","`print(tours[i], prices[i])` с запятой печатает через пробел; цену печатаем как строку, `int` для вывода не нужен."],"mist":["`<=` вместо `<`: тур с ценой ровно в бюджет попадёт зря.","Сравнили `prices[i] < budget` без `int`: строка с числом — ошибка `TypeError`.","Напечатали только название или только цену, а нужно обе."],"trace":""},{"id":"B5","n":5,"pts":0.75,"title":"Страны только у Ани","topics":"множества, разность","text":"Две строки: страны, в которых побывала Аня, и страны, в которых побывал Борис (через пробел).\n\nНапечатайте через пробел страны, где была **только Аня**, в алфавитном порядке. Если таких нет, напечатайте пустую строку.","fin":"Две строки, страны через пробел.","fout":"Страны через пробел в алфавитном порядке или пустая строка.","pre":"","tests":[{"i":"Италия Испания Франция\nФранция Греция","o":"Испания Италия"},{"i":"Египет\nЕгипет","o":""},{"i":"Чехия Польша\nЛитва","o":"Польша Чехия"},{"i":"Турция Греция\nГреция Турция Италия","o":""},{"i":"Япония Китай Корея\nКорея","o":"Китай Япония"}],"sol":"anna = set(input().split())\nboris = set(input().split())\n\nprint(*sorted(anna - boris))","hint":"Превратите обе строки во множества. «Только у Ани» — это разность `-`. Затем отсортируйте и распечатайте через `print(*...)`.","idea":"Страны Ани минус страны Бориса: остаётся то, чего у Бориса нет.","steps":["`set(input().split())` — строка → список → множество.","`anna - boris` — элементы первого множества, которых нет во втором.","`sorted(...)` даёт список по алфавиту.","`print(*список)` печатает через пробел; для пустого списка получится пустая строка."],"mist":["`boris - anna`: порядок вычитания важен, получатся страны только Бориса.","`print(anna - boris)` печатает фигурные скобки и случайный порядок.","Забыли `sorted`: порядок стран может отличаться от ожидаемого."],"trace":""},{"id":"B6","n":6,"pts":1.25,"title":"Языки для поездки","topics":"множества, разность и пересечение","text":"Три строки с названиями языков через запятую **без пробела** (в названиях пробелы бывают): языки, которые знает Аня; языки, которые знает Борис; языки, нужные для поездки.\n\nНапечатайте, сколько нужных для поездки языков знает **Аня, но не знает Борис**.","fin":"Три строки, языки через запятую.","fout":"Одно число.","pre":"","tests":[{"i":"Английский,Немецкий,Французский\nАнглийский,Испанский\nАнглийский,Немецкий,Французский,Итальянский","o":"2"},{"i":"А б,В г\nД е\nА б","o":"1"},{"i":"Китайский\nКитайский\nКитайский","o":"0"},{"i":"Польский,Чешский\nЧешский\nПольский,Чешский,Словацкий","o":"1"},{"i":"Греческий\nТурецкий\nАрабский","o":"0"}],"sol":"anna = set(input().split(','))\nboris = set(input().split(','))\nneed = set(input().split(','))\n\nonly_anna = anna - boris\nprint(len(only_anna & need))","hint":"Сначала найдите языки, которые знает только Аня (разность `-`), потом оставьте из них только нужные (пересечение `&`).","idea":"Сначала разность «Аня минус Борис», затем пересечение с нужными языками.","steps":["Разделитель — запятая без пробела: `.split(\",\")`. Без аргумента названия с пробелами разорвутся.","`anna - boris` — языки, которые знает Аня, но не Борис.","`only_anna & need` — из них только нужные для поездки.","`len(...)` — сколько их."],"mist":["`split()` вместо `split(\",\")`: названия с пробелом разорвутся.","`boris - anna`: получатся языки, которые знает Борис, но не Аня.","`|` вместо `&`: посчитаются все языки, а не только нужные."],"trace":""},{"id":"B7","n":7,"pts":0.75,"title":"Ученики с одной оценкой","topics":"словарь, перебор ключей","text":"В окне задан словарь `marks`: ученик → оценка за контрольную. Вводится оценка (целое число).\n\nНапечатайте учеников с этой оценкой, каждого с новой строки, в порядке словаря. Если таких нет, ничего не печатайте.","fin":"Одна строка — оценка (целое число).","fout":"Имена по одному на строке или пустой вывод.","pre":"marks = {'Аня': 5, 'Борис': 4, 'Вера': 5, 'Глеб': 3, 'Дарья': 4, 'Егор': 5}","tests":[{"i":"5","o":"Аня\nВера\nЕгор"},{"i":"4","o":"Борис\nДарья"},{"i":"3","o":"Глеб"},{"i":"2","o":""},{"i":"10","o":""}],"sol":"mark = int(input())\n\nfor name in marks:\n    if marks[name] == mark:\n        print(name)","hint":"Цикл `for name in marks` перебирает **ключи** (учеников). Оценка берётся как `marks[name]`. Введённая оценка — строка, нужен `int`.","idea":"Идём по ученикам и печатаем тех, у кого оценка совпадает с введённой.","steps":["`mark = int(input())` — оценки в словаре числа, значит и введённую нужно сделать числом.","`for name in marks:` — переменная `name` по очереди получает каждого ученика.","`marks[name] == mark` — совпадение оценки.","Печатаем `name`, а не оценку."],"mist":["Забыли `int(...)`: сравнение `5 == \"5\"` даёт `False`, ничего не напечатается.","Напечатали `marks[name]`: получится оценка вместо имени.","Ждали, что цикл даст значения: он перебирает ключи."],"trace":""},{"id":"B8","n":8,"pts":1.25,"title":"Маршруты с хорошим сервисом","topics":"словарь списков, min","text":"В окне задан словарь `routes`: маршрут → список оценок пассажиров (от 1 до 5). Вводится минимальная допустимая оценка.\n\nНапечатайте маршруты, у которых **все** оценки **не ниже** введённой, каждый с новой строки, в порядке словаря.","fin":"Одна строка — минимальная оценка (целое число).","fout":"Названия маршрутов по одному на строке или пустой вывод.","pre":"routes = {'Сочи': [4, 5, 3, 5], 'Байкал': [5, 5, 4, 5], 'Алтай': [3, 4, 4, 2], 'Крым': [4, 4, 5, 4]}","tests":[{"i":"4","o":"Байкал\nКрым"},{"i":"5","o":""},{"i":"3","o":"Сочи\nБайкал\nКрым"},{"i":"1","o":"Сочи\nБайкал\nАлтай\nКрым"},{"i":"2","o":"Сочи\nБайкал\nАлтай\nКрым"}],"sol":"need = int(input())\n\nfor route in routes:\n    if min(routes[route]) >= need:\n        print(route)","hint":"«Все оценки не ниже порога» — это то же, что «самая низкая оценка не ниже порога». Используйте `min`.","idea":"Вместо проверки каждой оценки сравниваем с порогом минимум в списке.","steps":["`routes[route]` — список оценок маршрута.","`min(...)` — самая низкая оценка.","Если самая низкая не ниже порога, то и все остальные не ниже. «Не ниже» — это `>=`.","Печатаем **ключ** `route`, а не список."],"mist":["`max` вместо `min`: условие станет «хотя бы одна оценка не ниже порога».","`>` вместо `>=`: маршрут с минимумом ровно на пороге пропадёт.","Напечатали `routes[route]` — список оценок вместо названия."],"trace":""},{"id":"B9","n":9,"pts":1.5,"title":"Дни одной недели","topics":"цикл, целочисленное деление","text":"Дни года пронумерованы подряд: дни 1–7 — неделя 1, дни 8–14 — неделя 2 и так далее.\n\nПервая строка — номера дней через пробел. Вторая — номер недели. Напечатайте, сколько введённых дней приходится на эту неделю.","fin":"Две строки: номера дней, номер недели.","fout":"Одно число.","pre":"","tests":[{"i":"1 5 7 8 14 15\n1","o":"3"},{"i":"7 8 9 14 15\n2","o":"3"},{"i":"100 101 99\n15","o":"3"},{"i":"3 10 17\n3","o":"1"},{"i":"21 22\n4","o":"1"},{"i":"1 2 3 4 5 6 7 8\n1","o":"7"},{"i":"50\n8","o":"1"},{"i":"1 8 15 22 29\n2","o":"1"}],"sol":"days = input().split()\nweek = int(input())\n\ncount = 0\nfor day in days:\n    if (int(day) - 1) // 7 + 1 == week:\n        count += 1\n\nprint(count)","hint":"Номер недели для дня `d` — `(d - 1) // 7 + 1`. Счётчик создайте до цикла.","idea":"Для каждого дня считаем номер его недели и сравниваем с введённым.","steps":["`int(day)` — дни нужны числами.","`(int(day) - 1) // 7 + 1`: день 7 даёт 6 // 7 = 0, неделя 1; день 8 даёт 7 // 7 = 1, неделя 2.","`count = 0` до цикла, `count += 1` на каждом подходящем.","Печатаем итог после цикла."],"mist":["`int(day) // 7 + 1` без `- 1`: день 7 уйдёт в неделю 2, а должен остаться в неделе 1.","Забыли `int`: `-` и `//` со строкой — ошибка.","Счётчик обнулили внутри цикла."],"trace":"Проверка: день 7 → (7 - 1) // 7 + 1 = 0 + 1 = 1. День 8 → 7 // 7 + 1 = 2. День 14 → 13 // 7 + 1 = 2. День 15 → 14 // 7 + 1 = 3."},{"id":"B10","n":10,"pts":1.5,"title":"Самый дешёвый маршрут","topics":"while True, словарь-накопитель, минимум","text":"Вводятся строки вида `маршрут,сумма` (сумма — целое **положительное** число: стоимость одной продажи), пока не будет введено слово `END`. Один маршрут может встретиться несколько раз.\n\nНайдите маршрут с **наименьшей суммарной** выручкой. Напечатайте его название и сумму через пробел. Гарантируется, что есть хотя бы одна строка. Если у нескольких одинаковый минимум — выведите того, кто встретился раньше.","fin":"Строки `маршрут,сумма`, последняя строка — `END`.","fout":"Название и сумма через пробел.","pre":"","tests":[{"i":"Сочи,50\nАлтай,20\nСочи,40\nАлтай,15\nБайкал,100\nEND","o":"Алтай 35"},{"i":"Крым,5\nEND","o":"Крым 5"},{"i":"А,10\nБ,10\nEND","o":"А 10"},{"i":"Х,100\nУ,50\nУ,60\nEND","o":"Х 100"},{"i":"Тур,7\nКруиз,3\nТур,2\nКруиз,9\nEND","o":"Тур 9"}],"sol":"totals = {}\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    route, price = line.split(',')\n    if route in totals:\n        totals[route] += int(price)\n    else:\n        totals[route] = int(price)\n\nworst = ''\nworst_sum = None\nfor route in totals:\n    if worst_sum is None or totals[route] < worst_sum:\n        worst_sum = totals[route]\n        worst = route\n\nprint(worst, worst_sum)","hint":"Два шага: (1) в цикле копите суммы в словаре; (2) после цикла найдите минимум. Стартовое значение для минимума — `None`: первое же значение его заменит. Для строгого сравнения берите `<`.","idea":"Сначала собираем словарь «маршрут → выручка», потом ищем ключ с наименьшим значением.","steps":["`totals = {}` — до цикла.","Если маршрут уже есть в словаре, прибавляем: `totals[route] += int(price)`, иначе создаём запись.","Для минимума нельзя стартовать с `0`: любая сумма больше нуля и не заменит его. Поэтому берём `None` и первое же значение его заменяет.","`<` (строго) оставляет первого из равных, как требует условие.","`print(worst, worst_sum)` с запятой печатает через пробел."],"mist":["Стартовое значение `0`: ни одна сумма не окажется меньше нуля, и ответом будет пустое имя.","`min(totals)` без `key` берёт минимум **по алфавиту названий**, а не по сумме.","`<=` вместо `<`: при равных суммах выберется последний, а не первый.","Забыли `int(price)`: строки склеиваются."],"trace":"Сочи: 50, затем 40 → 90. Алтай: 20, затем 15 → 35. Байкал: 100. Минимум 35 у Алтая. Словарь по шагам: `{Сочи: 50}` → `{Сочи: 50, Алтай: 20}` → `{Сочи: 90, Алтай: 20}` → …"}]},{"id":"C","name":"Вариант В","sub":"Транспорт и онлайн-магазин","tasks":[{"id":"C1","n":1,"pts":0.5,"title":"Проезд по зонам","topics":"if / elif / else, in, or","text":"В окне уже заданы список `zones` и три фразы: `free_msg`, `pay_msg`, `other_msg`. Вводятся зона и возраст пассажира.\n\nЕсли такой зоны нет в списке, напечатайте `other_msg`. Если зона есть и пассажиру меньше 7 лет или 65 и больше, напечатайте `free_msg`. Во всех остальных случаях напечатайте `pay_msg`.","fin":"Первая строка — зона, вторая — возраст (целое число).","fout":"Одна из трёх фраз.","pre":"zones = ['A', 'B', 'C']\nfree_msg = 'Проезд бесплатный'\npay_msg = 'Оплатите проезд'\nother_msg = 'Такой зоны нет'","tests":[{"i":"A\n5","o":"Проезд бесплатный"},{"i":"B\n30","o":"Оплатите проезд"},{"i":"D\n10","o":"Такой зоны нет"},{"i":"C\n65","o":"Проезд бесплатный"},{"i":"A\n7","o":"Оплатите проезд"},{"i":"B\n64","o":"Оплатите проезд"},{"i":"C\n6","o":"Проезд бесплатный"}],"sol":"zone = input()\nage = int(input())\n\nif zone not in zones:\n    print(other_msg)\nelif age < 7 or age >= 65:\n    print(free_msg)\nelse:\n    print(pay_msg)","hint":"Сначала отсеките несуществующие зоны (`not in`), потом проверьте возраст через `or`, остальное — `else`. Возраст — строка, нужен `int`.","idea":"Три исхода — цепочка `if / elif / else`: нет зоны; льгота по возрасту; обычный проезд.","steps":["`zone = input()` читает зону, `age = int(input())` читает возраст и сразу делает его числом.","`zone not in zones` — первая проверка: если зоны нет, возраст не важен.","`age < 7 or age >= 65` — льгота, если верно **хотя бы одно** из двух условий.","`else` — обычный проезд."],"mist":["Написали `age < 7 and age >= 65`: оба условия сразу не бывают верны, льготы не будет ни у кого.","Забыли `int(...)`: сравнение строки с числом — ошибка `TypeError`.","Границы: 7 лет уже платят, 65 лет — ещё бесплатно; перепутали `<` и `<=`."],"trace":""},{"id":"C2","n":2,"pts":1,"title":"Быстрые рейсы","topics":"while True, break, split, список","text":"Вводятся строки вида `рейс:минут` (время в пути, целое число), пока не будет введено слово `END`.\n\nНапечатайте список рейсов, которые идут **не дольше 90 минут**, в порядке ввода. Если таких нет, напечатайте пустой список.","fin":"Строки `рейс:минут`, последняя строка — `END`.","fout":"Список рейсов в квадратных скобках, как печатает `print(список)`.","pre":"","tests":[{"i":"Москва-Тула:80\nМосква-Казань:720\nМосква-Тверь:90\nEND","o":"['Москва-Тула', 'Москва-Тверь']"},{"i":"END","o":"[]"},{"i":"А-Б:100\nВ-Г:91\nEND","o":"[]"},{"i":"Д-Е:30\nЖ-З:45\nИ-К:10\nEND","o":"['Д-Е', 'Ж-З', 'И-К']"},{"i":"Л-М:90\nEND","o":"['Л-М']"}],"sol":"fast = []\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    trip, minutes = line.split(':')\n    if int(minutes) <= 90:\n        fast.append(trip)\n\nprint(fast)","hint":"Список создайте до цикла. Строку режьте по двоеточию: `trip, minutes = line.split(\":\")`. Время — строка, нужен `int`. «Не дольше» — это `<=`.","idea":"Читаем строки в бесконечном цикле, на слове `END` выходим через `break`, остальное разбираем и фильтруем.","steps":["`fast = []` создаём **до** цикла, иначе список обнулялся бы на каждой строке.","`while True:` — читаем, пока сами не прервём цикл.","`line == \"END\"` → `break`: выходим, не обрабатывая слово `END`.","`trip, minutes = line.split(\":\")` — две части строки в две переменные.","`int(minutes) <= 90` — «не дольше» включает ровно 90."],"mist":["Список создан внутри цикла — в конце останется только последний рейс.","Не сделали `int(minutes)`: сравнение строки с числом — ошибка `TypeError`.","Поставили `<`: рейс ровно на 90 минут пропадёт."],"trace":""},{"id":"C3","n":3,"pts":0.5,"title":"Список покупок","topics":"split(\", \"), not in, append, join","text":"В первой строке товары из списка покупок через «запятая + пробел». Во второй — новый товар.\n\nЕсли его ещё нет в списке, добавьте в конец. Затем напечатайте все товары **одной строкой через «запятая + пробел»** (без скобок и кавычек).","fin":"Первая строка — товары через `, `. Вторая — один товар.","fout":"Одна строка: товары через `, `.","pre":"","tests":[{"i":"хлеб, молоко\nсыр","o":"хлеб, молоко, сыр"},{"i":"хлеб, молоко\nхлеб","o":"хлеб, молоко"},{"i":"чай\nкофе","o":"чай, кофе"},{"i":"а, б, в\nа","o":"а, б, в"},{"i":"яблоки\nЯблоки","o":"яблоки, Яблоки"}],"sol":"items = input().split(', ')\nnew_item = input()\n\nif new_item not in items:\n    items.append(new_item)\n\nprint(', '.join(items))","hint":"Разбейте строку `split(\", \")`, добавьте товар, если его нет, и склейте обратно `\", \".join(...)`.","idea":"Строка → список → при необходимости добавляем → снова строка.","steps":["`split(\", \")` — строка → список.","`not in` + `append` — добавляем только новый товар.","`\", \".join(items)` склеивает элементы через «запятая + пробел»."],"mist":["`print(items)` печатает со скобками и кавычками.","`join` вызывают у **строки-разделителя**: `\", \".join(items)`, а не `items.join(\", \")`.","Регистр важен: `яблоки` и `Яблоки` — разные товары."],"trace":""},{"id":"C4","n":4,"pts":1,"title":"Дорогие товары","topics":"два списка, range(len())","text":"В первой строке названия товаров через пробел, во второй — их цены (целые числа) в том же порядке. В третьей — порог цены.\n\nНапечатайте названия товаров, цена которых **строго больше** порога, каждое с новой строки.","fin":"Три строки: названия, цены, порог.","fout":"Названия по одному на строке или пустой вывод.","pre":"","tests":[{"i":"чайник фен утюг лампа\n2500 1800 3200 900\n2000","o":"чайник\nутюг"},{"i":"А Б\n100 200\n500","o":""},{"i":"Телефон\n30000\n29999","o":"Телефон"},{"i":"Х У Ф\n10 20 30\n20","o":"Ф"},{"i":"Лампа Шкаф\n50 90\n10","o":"Лампа\nШкаф"}],"sol":"goods = input().split()\nprices = input().split()\nlimit = int(input())\n\nfor i in range(len(goods)):\n    if int(prices[i]) > limit:\n        print(goods[i])","hint":"Товары и цены лежат в двух списках, связь между ними — одинаковый номер. Переберите номера через `range(len(...))`. Цены — строки, нужен `int`.","idea":"Идём по номерам: по номеру берём и товар, и цену, сравниваем цену с порогом.","steps":["`goods` и `prices` — списки **строк**; цену берём как `int(prices[i])`.","`range(len(goods))` — номера 0, 1, 2, …","`int(prices[i]) > limit` — «строго больше», то есть `>`.","Печатаем `goods[i]` — товар с тем же номером."],"mist":["`>=` вместо `>`: товар с ценой ровно как порог попадёт зря.","Сравнили `prices[i] > limit` без `int`: строка с числом — ошибка `TypeError`.","Напечатали `prices[i]` вместо `goods[i]`."],"trace":""},{"id":"C5","n":5,"pts":0.75,"title":"Города доставки","topics":"множества, объединение","text":"Две строки: города, в которые ездит первый курьер, и города второго (через пробел).\n\nНапечатайте, сколько **различных** городов обслуживают курьеры вместе.","fin":"Две строки, города через пробел.","fout":"Одно число.","pre":"","tests":[{"i":"Москва Тверь Тула\nТула Рязань","o":"4"},{"i":"Омск\nОмск","o":"1"},{"i":"А Б В\nГ Д","o":"5"},{"i":"Сочи\nСочи Адлер Туапсе","o":"3"},{"i":"Казань Уфа Пермь\nПермь Уфа Казань","o":"3"}],"sol":"first = set(input().split())\nsecond = set(input().split())\n\nprint(len(first | second))","hint":"Превратите обе строки во множества. «Вместе, без повторов» — это объединение `|`.","idea":"Объединение двух множеств хранит каждый город один раз, даже если он есть у обоих курьеров.","steps":["`set(input().split())` — строка → список → множество.","`first | second` — города хотя бы одного курьера, без повторов.","`len(...)` — сколько их."],"mist":["Сложили `len(first) + len(second)`: общий город посчитается дважды.","`&` вместо `|`: получатся только города, общие для обоих.","`first + second`: сложение множеств не работает, будет `TypeError`."],"trace":""},{"id":"C6","n":6,"pts":1.25,"title":"Товары в одном магазине","topics":"множества, симметричная разность и пересечение","text":"Три строки с названиями товаров через запятую **без пробела** (в названиях пробелы бывают): товары первого магазина; товары второго магазина; список желаний покупателя.\n\nНапечатайте, сколько товаров из списка желаний есть **ровно в одном** из двух магазинов.","fin":"Три строки, товары через запятую.","fout":"Одно число.","pre":"","tests":[{"i":"Чайник,Фен,Утюг\nФен,Лампа,Тостер\nФен,Лампа,Утюг,Миксер","o":"2"},{"i":"А б,В г\nВ г\nА б,В г","o":"1"},{"i":"Х\nХ\nХ","o":"0"},{"i":"Ноутбук,Мышь\nКлавиатура\nМышь,Монитор","o":"1"},{"i":"Стол,Стул\nСтул,Шкаф\nДиван","o":"0"}],"sol":"first = set(input().split(','))\nsecond = set(input().split(','))\nwish = set(input().split(','))\n\none = first ^ second\nprint(len(one & wish))","hint":"«Ровно в одном магазине» — симметрическая разность `^`. Потом пересеките результат `&` со списком желаний.","idea":"Сначала товары, которые есть только в одном из двух магазинов (`^`), затем оставляем только желаемые (`&`).","steps":["Разделитель — запятая без пробела: `.split(\",\")`. Без аргумента названия с пробелами разорвутся.","`first ^ second` — товары, которые есть в одном магазине, но не в обоих.","`one & wish` — из них только желаемые.","`len(...)` — сколько их."],"mist":["`|` вместо `^`: посчитаются и товары, которые есть в обоих магазинах.","`split()` вместо `split(\",\")`: «А б» разорвётся на два товара.","Пересекли `first & second & wish`: получатся товары из обоих магазинов — противоположное условию."],"trace":""},{"id":"C7","n":7,"pts":0.75,"title":"Недорогие товары","topics":"словарь, перебор ключей","text":"В окне задан словарь `price`: товар → цена. Вводится предельная цена (целое число).\n\nНапечатайте товары, цена которых **не больше** предельной, каждый с новой строки, в порядке словаря. Если таких нет, ничего не печатайте.","fin":"Одна строка — предельная цена (целое число).","fout":"Названия по одному на строке или пустой вывод.","pre":"price = {'хлеб': 50, 'молоко': 90, 'сыр': 400, 'чай': 150, 'сахар': 80, 'кофе': 600}","tests":[{"i":"100","o":"хлеб\nмолоко\nсахар"},{"i":"50","o":"хлеб"},{"i":"500","o":"хлеб\nмолоко\nсыр\nчай\nсахар"},{"i":"10","o":""},{"i":"600","o":"хлеб\nмолоко\nсыр\nчай\nсахар\nкофе"}],"sol":"limit = int(input())\n\nfor item in price:\n    if price[item] <= limit:\n        print(item)","hint":"Цикл `for item in price` перебирает **ключи** (товары). Цена берётся как `price[item]`. Введённый порог — строка, нужен `int`.","idea":"Идём по товарам и печатаем те, у которых цена не больше порога.","steps":["`limit = int(input())` — цены в словаре числа, значит и порог нужно сделать числом.","`for item in price:` — переменная `item` по очереди получает каждый товар.","`price[item] <= limit` — «не больше», то есть `<=`.","Печатаем `item`, а не цену."],"mist":["Забыли `int(...)`: сравнение `50 <= \"100\"` — ошибка `TypeError`.","`<` вместо `<=`: товар с ценой ровно как порог пропадёт.","Напечатали `price[item]`: получится цена вместо названия."],"trace":""},{"id":"C8","n":8,"pts":1.25,"title":"Курьеры с хорошей средней","topics":"словарь списков, sum / len","text":"В окне задан словарь `couriers`: курьер → список числа доставок за пять дней. Вводится порог.\n\nНапечатайте курьеров, у которых **среднее** число доставок в день **строго больше** порога, каждого с новой строки, в порядке словаря.","fin":"Одна строка — порог (целое число).","fout":"Имена курьеров по одному на строке или пустой вывод.","pre":"couriers = {'Аня': [10, 12, 8, 11, 9], 'Борис': [5, 7, 6, 4, 8], 'Вера': [15, 14, 16, 12, 13], 'Глеб': [9, 10, 10, 9, 12]}","tests":[{"i":"10","o":"Вера"},{"i":"6","o":"Аня\nВера\nГлеб"},{"i":"14","o":""},{"i":"0","o":"Аня\nБорис\nВера\nГлеб"},{"i":"20","o":""}],"sol":"limit = int(input())\n\nfor name in couriers:\n    average = sum(couriers[name]) / len(couriers[name])\n    if average > limit:\n        print(name)","hint":"Среднее — это `sum(список) / len(список)`. Посчитайте его для каждого курьера и сравните с порогом.","idea":"Для каждого ключа берём список, делим сумму на длину и сравниваем среднее с порогом.","steps":["`couriers[name]` — список доставок курьера.","`sum(...)` — сумма, `len(...)` — количество дней; `/` даёт среднее.","`average > limit` — строго больше порога.","Печатаем `name`, а не среднее."],"mist":["Забыли разделить на `len(...)`: сравнится сумма, а не среднее.","Использовали `//` вместо `/`: среднее округлится вниз, и граница сдвинется.","`>=` вместо `>`: курьер со средним ровно как порог попадёт зря."],"trace":"Аня: 10 + 12 + 8 + 11 + 9 = 50, делим на 5 → 10. Борис: 5 + 7 + 6 + 4 + 8 = 30 → 6. Вера: 70 → 14. Глеб: 50 → 10. При пороге 10 строго больше только у Веры."},{"id":"C9","n":9,"pts":1.5,"title":"Вагоны по местам","topics":"цикл, целочисленное деление","text":"Места в поезде пронумерованы подряд: в первом вагоне места с 1 по N, во втором с N + 1 по 2N и так далее.\n\nПервая строка — номера мест через пробел. Вторая — N, число мест в вагоне. Напечатайте через пробел номера вагонов для этих мест в том же порядке.","fin":"Две строки: номера мест, число мест в вагоне.","fout":"Номера вагонов через пробел.","pre":"","tests":[{"i":"1 36 37 72 73\n36","o":"1 1 2 2 3"},{"i":"100\n36","o":"3"},{"i":"216 217\n36","o":"6 7"},{"i":"5 20 35\n36","o":"1 1 1"},{"i":"4 5 8 9\n4","o":"1 2 2 3"}],"sol":"seats = input().split()\nsize = int(input())\n\ncars = []\nfor seat in seats:\n    cars.append((int(seat) - 1) // size + 1)\n\nprint(*cars)","hint":"Номер вагона для места `s` — `(s - 1) // N + 1`. Список номеров соберите через `append` и распечатайте `print(*список)`.","idea":"Для каждого места считаем номер вагона по формуле и складываем номера в список.","steps":["`int(seat)` — места нужны числами.","`(int(seat) - 1) // size + 1`: место 36 при N = 36 даёт 35 // 36 = 0, вагон 1; место 37 даёт 36 // 36 = 1, вагон 2.","`cars = []` до цикла, `append` внутри.","`print(*cars)` печатает элементы через пробел."],"mist":["`int(seat) // size + 1` без `- 1`: последнее место вагона уйдёт в следующий.","Забыли `int`: `-` и `//` со строкой — ошибка.","`print(cars)` печатает скобки и запятые."],"trace":"Проверка при N = 36: место 36 → 35 // 36 + 1 = 1. Место 37 → 36 // 36 + 1 = 2. Место 72 → 71 // 36 + 1 = 2. Место 73 → 72 // 36 + 1 = 3."},{"id":"C10","n":10,"pts":1.5,"title":"Продажи по товарам","topics":"while True, словарь-накопитель, сортировка","text":"Вводятся строки вида `товар,количество` (количество — целое число), пока не будет введено слово `END`. Один товар может встретиться несколько раз.\n\nНапечатайте все товары в алфавитном порядке, каждый с новой строки, в виде `товар количество` (суммарное). В последней строке напечатайте общее количество проданного по всем товарам.","fin":"Строки `товар,количество`, последняя строка — `END`.","fout":"Строки `товар количество`, затем одно число.","pre":"","tests":[{"i":"чай,30\nкофе,20\nчай,25\nсахар,5\nEND","o":"кофе 20\nсахар 5\nчай 55\n80"},{"i":"мёд,7\nEND","o":"мёд 7\n7"},{"i":"б,10\nа,1\nб,2\nEND","o":"а 1\nб 12\n13"},{"i":"Х,100\nУ,50\nУ,60\nEND","o":"У 110\nХ 100\n210"}],"sol":"totals = {}\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    item, count = line.split(',')\n    if item in totals:\n        totals[item] += int(count)\n    else:\n        totals[item] = int(count)\n\nfor item in sorted(totals):\n    print(item, totals[item])\n\nprint(sum(totals.values()))","hint":"Копите суммы в словаре, как в предыдущих задачах, а после цикла напечатайте `sorted(totals)` и `sum(totals.values())`.","idea":"Сначала собираем словарь «товар → сумма», потом печатаем его по алфавиту и в конце общую сумму.","steps":["`totals = {}` — до цикла.","Если товар уже есть в словаре, прибавляем: `totals[item] += int(count)`, иначе создаём запись.","`sorted(totals)` — ключи по алфавиту.","`print(item, totals[item])` — через пробел.","`sum(totals.values())` — сумма всех значений словаря, печатаем после цикла."],"mist":["Забыли `sorted`: порядок будет порядком добавления.","Напечатали сумму внутри цикла: она повторится на каждой строке.","Забыли `int(count)`: строки склеиваются, а не складываются."],"trace":"Чай: 30, затем 25 → 55. Кофе: 20. Сахар: 5. По алфавиту: `кофе`, `сахар`, `чай`. Общая сумма 55 + 20 + 5 = 80."}]}];

