function paras(s){return String(s).split(/\n\n+/).map(function(p){return '<p>'+inl(p).replace(/\n/g,'<br>')+'</p>'}).join('')}
/* ---------- хранилище ---------- */
var P={code:{},tr:{},ex:{}};
